    const address = await new Promise((resolve, reject) => {
      const timer = setTimeout(() => reject(new Error('Firefox startup timed out')), 20000);
      const inspect = chunk => { const match = /WebDriver BiDi listening on (ws:\/\/127\.0\.0\.1:\d+)/.exec(chunk.toString()); if (match) { clearTimeout(timer); resolve(match[1] + '/session'); } };
      firefox.stdout.on('data', inspect); firefox.stderr.on('data', inspect); firefox.on('error', reject);
    });
    driver = new WebSocket(address); await once(driver, 'open');
    let sequence = 0; const waiting = new Map();
    driver.on('message', raw => { const message = JSON.parse(raw); const request = waiting.get(message.id); if (!request) return;
      clearTimeout(request.timer); waiting.delete(message.id); message.type === 'error' ? request.reject(new Error(message.message)) : request.resolve(message.result);
    });
    const command = (method, params = {}) => new Promise((resolve, reject) => {
      const id = ++sequence, timer = setTimeout(() => { waiting.delete(id); reject(new Error(method + ' timed out')); }, 15000);
      waiting.set(id, { resolve, reject, timer }); driver.send(JSON.stringify({ id, method, params }));
    });
